import { createStore } from '@stencil/store';
import type { Locale } from '@fe-infra/keystone-locales';
import { getDefaultLocale, loadTimezoneInfo } from '@src/integrations';
import { normalizeTimezoneInfo, timezoneToTimezoneInfo, TimezoneInfo } from '@src/shared/timezone';
import { isEqual } from 'lodash-es';

/** @internal Internal meta info/state about the global store. */
export const _storeMeta = {
  isTimezoneManuallySet: false,
};

export const globalConfigStore = createStore<{
  locale: Locale;
  /**
   * The global timezone setting for all date-time operations. Components can override this with their own `timezone` prop.
   * If not set, it may default to:
   * - The user's account timezone, if using in X account system domains,
   * - Else, the UTC+0 fixed timezone (which is more predictable in B2B systems than the user's browser timezone), without label and help content.
   *
   * The `Keystone.config` provides a `'local'` shortcut for `timezone` if it's intended use.
   */
  timezone: TimezoneInfo;
}>(() => {
  initAsyncState();
  return {
    locale: getDefaultLocale(),
    timezone: timezoneToTimezoneInfo('UTC'),
  };
});

function initAsyncState() {
  loadTimezoneInfo().then((timezoneInfo) => {
    if (!_storeMeta.isTimezoneManuallySet && timezoneInfo) {
      const oldTimezoneInfo = globalConfigStore.get('timezone');
      const normalizedTimezoneInfo = normalizeTimezoneInfo(timezoneInfo, oldTimezoneInfo);
      if (!isEqual(normalizedTimezoneInfo, oldTimezoneInfo)) {
        globalConfigStore.set('timezone', normalizedTimezoneInfo);
      }
    }
  });
}

/**
 * Configures the global settings of Keystone.
 * This will setup globally for all components.
 * Call this function multiple times will update the config with shallow merge.
 *
 * @param config - The configuration object.
 * @param config.locale - The locale to set.
 * @param config.timezone - The timezone info to set.
 * @returns The global config state.
 */
export function config(config?: { locale?: Locale; timezone?: TimezoneInfo }) {
  if (config) {
    if (config.locale) {
      globalConfigStore.set('locale', config.locale);
    }
    if (config.timezone) {
      globalConfigStore.set('timezone', normalizeTimezoneInfo(config.timezone));
    }
  }

  return globalConfigStore.state;
}
