import { commonMessages, datePickerMessages } from '@fe-infra/keystone-locales';
import { TimezoneInfo } from '@src/shared/timezone';
import { globalThisAsyncCache } from '@src/shared/perf/cache';
import { t } from '@src/shared/i18n';

export const aadvid = new URLSearchParams(window.location.search).get('aadvid') || '';

// TODO 增加未命中的 Slardar 报警？
export const isTTAM = Boolean(aadvid) && ['ads.tiktok.com', 'boei18n-ads.byteoversea.net'].includes(location.host);

/** TTAM accounts only has a **fixed** utcOffset, which is **not** a IANA timezone. */
export const loadTimezoneInfoOfTTAM = globalThisAsyncCache(
  'ttamMain-loadTimezoneInfo',
  async (): Promise<TimezoneInfo | undefined> => {
    try {
      const res = await fetch(`/api/v3/i18n/account/extra/?aadvid=${aadvid}`);
      const {
        data: {
          timezone: { value: utcOffset },
        },
      } = await res.json();
      if (typeof utcOffset !== 'number') {
        return undefined;
      }
      return {
        utcOffset,
        helpContent: `${t(
          datePickerMessages.timezoneTip,
        )}<a size="sm" href="https://ads.tiktok.com/help/article/about-timezone-converter-in-tiktok-ads-manager">${t(
          commonMessages.learnMore,
        )}</a>`,
      };
    } catch (e) {
      return undefined;
    }
  },
);
