import { Timezone, TimezoneInfo } from './types';

const ianaTimezoneValidationCache = new Map<string, boolean>();

export function isValidIanaTimezoneId(id?: string): id is string {
  if (!id) {
    return false;
  }

  const cached = ianaTimezoneValidationCache.get(id);
  if (cached !== undefined) {
    return cached;
  }

  let isValid = false;

  try {
    new Intl.DateTimeFormat('en-US', { timeZone: id });
    isValid = true;
  } catch {
    /* keep isValid false */
  }

  ianaTimezoneValidationCache.set(id, isValid);

  return isValid;
}

export function normalizeTimezoneInfo(
  timezone?: TimezoneInfo,
  fallback: TimezoneInfo = { utcOffset: 0 },
): TimezoneInfo {
  if (!timezone) {
    return fallback;
  }

  if (Number.isInteger(timezone.utcOffset)) {
    return timezone;
  }

  if (isValidIanaTimezoneId(timezone.id)) {
    return timezone;
  }

  return fallback;
}

export function timezoneToTimezoneInfo(timezone: Timezone): TimezoneInfo {
  if (timezone === 'UTC') {
    return { utcOffset: 0 };
  } else if (timezone === 'local') {
    return normalizeTimezoneInfo({ id: Intl.DateTimeFormat().resolvedOptions().timeZone });
  } else {
    return normalizeTimezoneInfo(timezone);
  }
}
