import { isSupportedLocale, Locale } from '@fe-infra/keystone-locales';
import { TimezoneInfo } from '@src/shared/timezone';
import { isTTAM, loadTimezoneInfoOfTTAM } from '@src/integrations/platform/ttam';

export async function loadTimezoneInfo(): Promise<TimezoneInfo | undefined> {
  try {
    if (isTTAM) {
      return await loadTimezoneInfoOfTTAM();
    }
  } catch (e) {
    return;
  }

  return;
}

export function getDefaultLocale(): Locale {
  try {
    const localeInSharedGMPTCookie = document.cookie.match(/(^|;\s*)lang_type=([^;]*)/)?.pop() || '';
    if (isSupportedLocale(localeInSharedGMPTCookie)) {
      return localeInSharedGMPTCookie;
    }
  } catch (e) {
    // do nothing
  }

  return 'en';
}
