import { isEqual } from 'lodash-es';

// @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
export function cacheOrUpdate<Key, Value>(key: Key, updateCache: (key: Key, options) => Value, options?) {
  let cachedKey = key + JSON.stringify(options);
  let cachedValue = updateCache(key, options);

  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  return (key: Key, options?) => {
    if (key !== cachedKey) {
      cachedValue = updateCache(key, options);
      cachedKey = key + JSON.stringify(options);
    }
    return cachedValue;
  };
}

/** Store memory cache to globalThis to be shared across different version of the package */
export function globalThisAsyncCache<T>(key: string, fn: () => Promise<T>): () => Promise<T> {
  let globalObj: typeof globalThis;
  try {
    globalObj = globalThis || window || global;
  } catch (e) {
    /* do nothing */
  }

  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  const cache: Map<string, Promise<unknown>> = (globalObj.__keystone_global_cache__ ||= new Map());

  return () => {
    let pendingOrResolvedPromise = cache.get(key) as Promise<T> | undefined;
    if (!pendingOrResolvedPromise) {
      pendingOrResolvedPromise = fn();
      cache.set(key, pendingOrResolvedPromise);
      pendingOrResolvedPromise.catch(() => cache.delete(key));
    }

    return pendingOrResolvedPromise;
  };
}

/** @internal */
function _cached<T extends object | null, U>(getter: (cacheKey: T) => U) {
  const weakMap = new WeakMap<object, U>();
  let nullKeyedCacheValue: U;

  return (cacheKey: T) => {
    if (cacheKey === null) {
      if (nullKeyedCacheValue === undefined) {
        nullKeyedCacheValue = getter(cacheKey);
      }
      return nullKeyedCacheValue;
    } else {
      let cachedValue = weakMap.get(cacheKey);
      if (cachedValue === undefined) {
        cachedValue = getter(cacheKey);
        weakMap.set(cacheKey, cachedValue);
      }
      return cachedValue;
    }
  };
}
export function memoizedCallback<T extends object>(callback: (cacheKey: T) => void): (cacheKey: T) => () => void {
  return _cached((cacheKey: T) => () => callback(cacheKey));
}

const simpleEqual = (a: unknown, b: unknown) => a === b;
export function computed<T extends unknown[], U>(getter: (...deps: T) => U, options?: { deepEqual?: boolean }) {
  let lastDeps: T;
  let lastValue: U;
  const equal = options?.deepEqual ? isEqual : simpleEqual;
  return (...deps: T) => {
    if (
      // eslint-disable-next-line no-autofix/@typescript-eslint/no-unnecessary-condition
      lastDeps === undefined ||
      deps.length !== lastDeps.length ||
      deps.some((dep, index) => !equal(dep, lastDeps[index]))
    ) {
      lastValue = getter(...deps);
      lastDeps = deps;
    }
    return lastValue;
  };
}
